<#
============================================================================
 collect_all.ps1  -  UM UNICO ARQUIVO que roda TODOS os coletores.

 Os 5 coletores estao EMBUTIDOS aqui (base64, byte-exato). Ao rodar, o script
 os extrai para uma pasta temporaria, executa cada um gerando um .ndjson por
 tipo em -OutputDir, e apaga a pasta temporaria no fim.

 Janela de coleta (Performance e Offload): 900 horas (~37 dias) por padrao,
 garantindo o mes inteiro. Ajuste com -Hours se quiser.

 Gera SOMENTE .ndjson (sem .pretty.json / .csv). Depois suba os arquivos em
 "Importar PowerShell" (deteccao automatica).

 SOMENTE LEITURA. PowerShell 5.1 ou 7. Rodar no servidor VBR.
 Copie APENAS este arquivo - nao precisa dos coletores separados.
============================================================================
#>
param(
    [string]$VbrServer = "localhost",
    [string]$OutputDir = "C:\temp\veeam-coletas",
    [int]   $Hours     = 900,     # janela p/ Performance e Offload (900h = ~37 dias)
    [switch]$WithExtent,          # detalhe de extent/tier no coletor de disco (mais lento)
    [switch]$Pretty               # tambem grava .pretty.json do job_config
)

$ErrorActionPreference = "Continue"
if (-not (Test-Path -LiteralPath $OutputDir)) {
    New-Item -ItemType Directory -Path $OutputDir -Force | Out-Null
}

# --- coletores embutidos (base64) ------------------------------------------
$Embedded = @{
    "collect_job_config.ps1" = ""
    "collect_disk_backups.ps1" = ""
    "collect_repo_capacity.ps1" = ""
    "collect_backups.ps1" = ""
    "SOBR.ps1" = ""
}

# --- extrai para pasta temporaria ------------------------------------------
$tmp = Join-Path $env:TEMP ("veeamcol_" + [guid]::NewGuid().ToString("N"))
New-Item -ItemType Directory -Path $tmp -Force | Out-Null
foreach ($name in $Embedded.Keys) {
    $bytes = [Convert]::FromBase64String($Embedded[$name])
    [System.IO.File]::WriteAllBytes((Join-Path $tmp $name), $bytes)
}

Write-Host ("Saida: {0}" -f $OutputDir) -ForegroundColor Cyan
Write-Host ("VBR:   {0}  |  janela Performance/Offload: {1}h" -f $VbrServer, $Hours) -ForegroundColor DarkGray

$steps = @(
    @{ n = "Config de Rotinas"; f = "collect_job_config.ps1"; a = @{ VbrServer = $VbrServer; OutputDir = $OutputDir; CollectAllJobs = $true; Pretty = [bool]$Pretty } },
    @{ n = "Backups em Disco"; f = "collect_disk_backups.ps1"; a = @{ VbrServer = $VbrServer; OutputDir = $OutputDir; WithExtent = [bool]$WithExtent } },
    @{ n = "Capacidade do Repo"; f = "collect_repo_capacity.ps1"; a = @{ VbrServer = $VbrServer; OutputDir = $OutputDir } },
    @{ n = "Performance de Backup"; f = "collect_backups.ps1"; a = @{ VbrServer = $VbrServer; OutputDir = $OutputDir; Hours = $Hours; Yes = $true } },
    @{ n = "Offload"; f = "SOBR.ps1"; a = @{ VbrServer = $VbrServer; OutputDir = $OutputDir; Hours = $Hours } }
)

$ok = 0; $fail = 0
try {
    foreach ($s in $steps) {
        Write-Host ("`n===== {0} =====" -f $s.n) -ForegroundColor Cyan
        $script = Join-Path $tmp $s.f
        try {
            $splat = $s.a
            & $script @splat
            $ok++
        } catch {
            Write-Host ("  FALHOU: {0}" -f $_.Exception.Message) -ForegroundColor Red
            $fail++
        }
    }
} finally {
    Remove-Item -LiteralPath $tmp -Recurse -Force -ErrorAction SilentlyContinue
}

Write-Host ("`n===== FIM: {0} coletor(es) OK, {1} falha(s) =====" -f $ok, $fail) -ForegroundColor Green
Write-Host ("Arquivos .ndjson em: {0}" -f $OutputDir) -ForegroundColor Green
Write-Host "Agora suba esses .ndjson em 'Importar PowerShell' (deteccao automatica)." -ForegroundColor DarkGray
